-- Engine-held values that never leave the engine through the API. The `hash` column mask
-- key (`mask_hmac_key`) is generated by the engine on first start: a plain SHA-256 of a
-- low-entropy value (phone number, national ID, birth date) is reversible by guessing, a
-- keyed HMAC is not, and equal inputs still mask to equal values for joins and counts.
CREATE TABLE engine_settings (
 key TEXT PRIMARY KEY,
 value TEXT NOT NULL
);
